import csv,json,math
rows=list(csv.DictReader(open('market.csv',encoding='utf-8')))
active={r['qid'] for r in rows if r['is_resolved']=='False'}
base=json.load(open('memory/baseline_forecasts.json'))
today=json.load(open('predictions/2026-04-24.json'))
errs=[]
for e in today:
 q=e['question_id']; o=e['outcomes']; s=sum(o.values())
 if q not in active: errs.append(f'{q} not active')
 if len(o)>5: errs.append(f'{q} has {len(o)} outcomes')
 if s>1+1e-9: errs.append(f'{q} sum={s}')
 if any(not (0<=v<=1) for v in o.values()): errs.append(f'{q} invalid probability')
 if any(k.lower() in {'unknown','tbd','other','n/a'} for k in o): errs.append(f'{q} placeholder')
 if base.get(q)"'!=o: errs.append(f'"'{q} baseline mismatch')
print('active',len(active),'baseline records',len(base),'active missing',len(active-set(base)))
print('today submissions',len(today),'unique qids',len({e['question_id'] for e in today}))
print('sums',[(e['question_id'],round(sum(e['outcomes'].values()),3),len(e['outcomes'])) for e in today])
print('validation', 'PASS' if not errs else errs)
PY"

